-- ==========================================================
-- Study Plug - JAMB UTME Database Schema & Past Questions
-- Compatible with cPanel MySQL 5.7+ / MariaDB 10.3+ / phpMyAdmin
-- ==========================================================

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
START TRANSACTION;
SET time_zone = "+00:00";

CREATE TABLE IF NOT EXISTS `subjects` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `code` varchar(20) NOT NULL UNIQUE,
  `total_questions` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `subjects` (`id`, `name`, `code`, `total_questions`) VALUES
(1, 'Physics', 'PHY', 60),
(2, 'Mathematics', 'MTH', 50),
(3, 'Chemistry', 'CHM', 0),
(4, 'Biology', 'BIO', 0),
(5, 'Use of English', 'ENG', 0)
ON DUPLICATE KEY UPDATE `name`=`name`;

CREATE TABLE IF NOT EXISTS `questions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `subject` varchar(50) NOT NULL DEFAULT 'Physics',
  `exam_year` int(11) NOT NULL,
  `question_num` int(11) NOT NULL,
  `text` text NOT NULL,
  `image_url` varchar(255) DEFAULT NULL,
  `image_svg` text DEFAULT NULL,
  `option_a` text NOT NULL,
  `option_b` text NOT NULL,
  `option_c` text NOT NULL,
  `option_d` text NOT NULL,
  `correct_answer` enum('A','B','C','D') NOT NULL,
  `explanation` text DEFAULT NULL,
  `topic` varchar(100) DEFAULT NULL,
  `difficulty` enum('Easy','Medium','Hard') DEFAULT 'Medium',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_subject_year` (`subject`,`exam_year`),
  KEY `idx_subject_topic` (`subject`,`topic`),
  KEY `idx_exam_year` (`exam_year`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `exam_sessions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `session_uuid` varchar(64) NOT NULL UNIQUE,
  `student_name` varchar(100) DEFAULT 'Student',
  `subject` varchar(50) NOT NULL,
  `exam_year` varchar(20) NOT NULL,
  `score` int(11) NOT NULL,
  `total_questions` int(11) NOT NULL,
  `accuracy` int(11) NOT NULL,
  `time_spent_seconds` int(11) NOT NULL,
  `completed_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_subject_date` (`subject`,`completed_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `youtube_projects` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `project_uuid` varchar(64) NOT NULL UNIQUE,
  `title` varchar(255) NOT NULL,
  `subject` varchar(50) NOT NULL,
  `exam` varchar(30) NOT NULL,
  `topic` varchar(150) NOT NULL,
  `subtopic` varchar(150) DEFAULT NULL,
  `video_type` varchar(50) NOT NULL,
  `aspect_ratio` varchar(10) NOT NULL DEFAULT '16:9',
  `status` enum('draft','script_ready','rendering','ready_for_review','published') DEFAULT 'draft',
  `script_json` mediumtext DEFAULT NULL,
  `scenes_json` mediumtext DEFAULT NULL,
  `seo_json` mediumtext DEFAULT NULL,
  `cost_estimate_naira` decimal(10,2) DEFAULT '0.00',
  `duration_seconds` int(11) DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_subject_topic` (`subject`,`topic`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `questions` (`subject`, `exam_year`, `question_num`, `text`, `image_url`, `image_svg`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_answer`, `explanation`, `topic`, `difficulty`) VALUES
('Physics', 1983, 1, 'In a resonance tube experiment, a tube of fixed length is closed at one end and several tuning forks of increasing frequency are used to obtain resonance at the open end. If the tuning fork with the lowest frequency which gave resonance had a frequency f₁ and the next tuning fork to give resonance had a frequency f₂, find the ratio f₂ / f₁.', NULL, NULL, '8', '3', '2', '1/2', 'B', 'For a pipe closed at one end, only odd harmonics are present. The fundamental frequency is f₁ = v / (4L). The next resonant frequency (the first overtone or 3rd harmonic) is f₂ = 3v / (4L). Therefore, the ratio f₂ / f₁ = 3.', 'Waves & Sound', 'Medium'),
('Physics', 1983, 2, 'Which of the following physical quantities is NOT a vector quantity?', NULL, NULL, 'Force', 'Altitude', 'Weight', 'Displacement', 'B', 'Altitude represents a vertical height (magnitude only) without directional vector orientation, making it a scalar quantity. Force, weight, and displacement are all vector quantities possessing both magnitude and direction.', 'Units & Vectors', 'Easy'),
('Physics', 1983, 3, 'The total length of a spring when a mass of 20 g is hung from its end is 14 cm, while its total length is 16 cm when a mass of 30 g is hung from the same end. Calculate the unstretched length of the spring assuming Hooke\'s law is obeyed.', NULL, NULL, '10.0 cm', '12.0 cm', '8.0 cm', '9.5 cm', 'A', 'By Hooke\'s law, extension e ∝ m. Let L₀ be unstretched length. e₁ = 14 - L₀ and e₂ = 16 - L₀. Thus, 20 / (14 - L₀) = 30 / (16 - L₀) ⇒ 2(16 - L₀) = 3(14 - L₀) ⇒ 32 - 2L₀ = 42 - 3L₀ ⇒ L₀ = 10.0 cm.', 'Elasticity', 'Medium'),
('Physics', 1983, 4, 'The refractive index of a liquid is 1.5. If the velocity of light in a vacuum is 3.0 × 10⁸ m/s, calculate the velocity of light in the liquid.', NULL, NULL, '1.5 × 10⁸ m/s', '2.0 × 10⁸ m/s', '3.0 × 10⁸ m/s', '4.5 × 10⁸ m/s', 'B', 'Refractive index n = c / v, where c is speed of light in vacuum and v is speed in the medium. v = c / n = (3.0 × 10⁸) / 1.5 = 2.0 × 10⁸ m/s.', 'Geometric Optics', 'Easy'),
('Physics', 1983, 5, 'Atmospheric pressure supports a column of mercury of height 76 cm. If the relative density of mercury is 13.6, calculate the height of a water column that can be supported by the same atmospheric pressure.', NULL, NULL, '5.59 m', '7.60 m', '10.34 m', '13.60 m', 'C', 'Pressure P = h_m ρ_m g = h_w ρ_w g. Therefore, h_w = h_m × (ρ_m / ρ_w) = 0.76 m × 13.6 = 10.336 m ≈ 10.34 m.', 'Hydrostatics', 'Medium'),
('Physics', 1985, 6, 'Which of the following is a fundamental SI unit?', NULL, NULL, 'Newton', 'Joule', 'Kelvin', 'Watt', 'C', 'The Kelvin (K) is the SI fundamental unit of thermodynamic temperature. Newton, Joule, and Watt are derived units (force, energy, and power).', 'Units & Dimensions', 'Easy'),
('Physics', 1985, 7, 'At what angle to the horizontal must a projectile be launched on level ground to achieve the maximum horizontal range?', NULL, NULL, '30°', '45°', '60°', '90°', 'B', 'The horizontal range is given by R = (u² sin 2θ) / g. Range is maximum when sin 2θ = 1, which means 2θ = 90° ⇒ θ = 45°.', 'Projectiles', 'Easy'),
('Physics', 1985, 8, 'Calculate the quantity of heat required to raise the temperature of 0.5 kg of water from 20°C to 50°C. (Specific heat capacity of water = 4200 J kg⁻¹ K⁻¹)', NULL, NULL, '21 kJ', '42 kJ', '63 kJ', '105 kJ', 'C', 'Heat Q = mcΔθ = 0.5 kg × 4200 J/(kg·K) × (50 - 20) K = 0.5 × 4200 × 30 = 63,000 J = 63 kJ.', 'Thermal Physics', 'Medium'),
('Physics', 1988, 9, 'What are the dimensions of Planck\'s constant (h)?', NULL, NULL, 'ML²T⁻¹', 'MLT⁻¹', 'ML²T⁻²', 'ML⁻¹T⁻¹', 'A', 'From E = hf, h = E / f. Dimension of Energy E = [Force × Distance] = ML²T⁻². Frequency [f] = T⁻¹. Therefore, [h] = (ML²T⁻²) / T⁻¹ = ML²T⁻¹.', 'Units & Dimensions', 'Medium'),
('Physics', 1988, 10, 'A body of mass 5 kg falls freely from rest from a height of 10 m above the ground. Calculate its kinetic energy just before hitting the ground. (g = 10 m/s²)', NULL, NULL, '50 J', '250 J', '500 J', '1000 J', 'C', 'By conservation of mechanical energy, the kinetic energy just before impact equals the initial gravitational potential energy: KE = mgh = 5 kg × 10 m/s² × 10 m = 500 J.', 'Work, Energy & Power', 'Easy'),
('Physics', 1988, 11, 'Three resistors of resistances 2 Ω, 3 Ω, and 6 Ω are connected in parallel. What is their combined equivalent resistance?', NULL, NULL, '1 Ω', '2 Ω', '3.6 Ω', '11 Ω', 'A', '1/R_eq = 1/R₁ + 1/R₂ + 1/R₃ = 1/2 + 1/3 + 1/6 = (3 + 2 + 1)/6 = 6/6 = 1 Ω⁻¹. Thus R_eq = 1 Ω.', 'Current Electricity', 'Easy'),
('Physics', 1990, 12, 'A car of mass 1000 kg rounds a circular curve of radius 50 m at a constant speed of 20 m/s. Calculate the centripetal force exerted on the car.', NULL, NULL, '4,000 N', '8,000 N', '10,000 N', '20,000 N', 'B', 'Centripetal force F = (m v²) / r = (1000 × 20²) / 50 = (1000 × 400) / 50 = 400,000 / 50 = 8,000 N.', 'Circular Motion', 'Medium'),
('Physics', 1990, 13, 'An echo sounder in a ship transmits a sound pulse and receives the reflected signal from the seabed 0.8 seconds later. If the speed of sound in seawater is 1500 m/s, calculate the depth of the sea.', NULL, NULL, '300 m', '600 m', '1200 m', '2400 m', 'B', 'The sound pulse travels down to the seabed and back (total distance = 2d). 2d = v × t ⇒ d = (v × t) / 2 = (1500 × 0.8) / 2 = 1200 / 2 = 600 m.', 'Waves & Sound', 'Medium'),
('Physics', 1990, 14, 'The volume of a fixed mass of gas at 27°C is 300 cm³. What will be its volume at 127°C if the pressure remains constant?', NULL, NULL, '350 cm³', '400 cm³', '450 cm³', '500 cm³', 'B', 'By Charles\'s law, V₁ / T₁ = V₂ / T₂. Convert temperatures to Kelvin: T₁ = 27 + 273 = 300 K, T₂ = 127 + 273 = 400 K. V₂ = V₁ × (T₂ / T₁) = 300 × (400 / 300) = 400 cm³.', 'Gas Laws', 'Medium'),
('Physics', 1995, 15, 'A solid object weighs 45 N in air and 30 N when completely submerged in water. Calculate the relative density of the object.', NULL, NULL, '1.5', '2.0', '3.0', '4.5', 'C', 'Relative density = (Weight in air) / (Upthrust in water). Upthrust = Weight in air - Apparent weight in water = 45 N - 30 N = 15 N. Relative density = 45 / 15 = 3.0.', 'Hydrostatics', 'Medium'),
('Physics', 1995, 16, 'A person who cannot focus clearly on distant objects but sees nearby objects well is diagnosed with myopia. Which type of lens is prescribed to correct this vision defect?', NULL, NULL, 'Bifocal lens', 'Diverging (concave) lens', 'Converging (convex) lens', 'Cylindrical lens', 'B', 'In a short-sighted (myopic) eye, rays from a distant object focus in front of the retina. A diverging (concave) lens spreads the light rays outwards before they enter the eye, allowing the image to form precisely on the retina.', 'Geometric Optics', 'Easy'),
('Physics', 1995, 17, 'A radioactive isotope has a half-life of 20 days. If an initial pure sample contains 80 g of the isotope, what mass of the undecayed isotope remains after 60 days?', NULL, NULL, '40 g', '20 g', '10 g', '5 g', 'C', 'Number of half-lives n = 60 / 20 = 3. Remaining mass N = N₀ × (1/2)ⁿ = 80 × (1/2)³ = 80 / 8 = 10 g.', 'Modern Physics', 'Medium'),
('Physics', 1998, 18, 'An ideal step-up transformer has 500 turns in its primary coil and 2500 turns in its secondary coil. If an alternating voltage of 240 V is applied across the primary coil, determine the secondary output voltage.', NULL, NULL, '48 V', '600 V', '1200 V', '2400 V', 'C', 'For an ideal transformer, V_s / V_p = N_s / N_p ⇒ V_s = V_p × (N_s / N_p) = 240 × (2500 / 500) = 240 × 5 = 1200 V.', 'Electromagnetism', 'Easy'),
('Physics', 1998, 19, 'Monochromatic light of frequency 8.0 × 10¹⁴ Hz is incident on a metal surface with a work function of 3.2 × 10⁻¹⁹ J. If Planck\'s constant is 6.63 × 10⁻³⁴ J s, calculate the maximum kinetic energy of the emitted photoelectrons.', NULL, NULL, '1.20 × 10⁻¹⁹ J', '2.10 × 10⁻¹⁹ J', '3.50 × 10⁻¹⁹ J', '5.30 × 10⁻¹⁹ J', 'B', 'By Einstein\'s photoelectric equation: E = hf = W₀ + KE_max. Energy of incident photon = (6.63 × 10⁻³⁴) × (8.0 × 10¹⁴) = 5.304 × 10⁻¹⁹ J. KE_max = E - W₀ = (5.304 - 3.2) × 10⁻¹⁹ = 2.104 × 10⁻¹⁹ J.', 'Modern Physics', 'Hard'),
('Physics', 1998, 20, 'What is the work done in moving a positive charge of 5 C between two points having a potential difference of 12 V?', NULL, NULL, '2.4 J', '17 J', '60 J', '120 J', 'C', 'Work done W = Q × V = 5 C × 12 V = 60 J.', 'Electrostatics', 'Easy'),
('Physics', 2000, 21, 'If the length of a simple pendulum is increased by a factor of 4, what happens to its period of oscillation T?', NULL, NULL, 'It is quadrupled (4T)', 'It is doubled (2T)', 'It is halved (T/2)', 'It remains unchanged', 'B', 'The period of a simple pendulum is T = 2π√(L/g). Since T ∝ √L, multiplying the length by 4 multiplies the period by √4 = 2. The period is doubled.', 'Oscillations & SHM', 'Medium'),
('Physics', 2000, 22, 'A block and tackle pulley system consisting of 5 pulleys has an efficiency of 80%. What effort is required to raise a load of 1000 N?', NULL, NULL, '200 N', '250 N', '300 N', '400 N', 'B', 'Velocity ratio VR = number of pulleys = 5. Efficiency = (MA / VR) × 100% ⇒ 0.80 = MA / 5 ⇒ MA = 4.0. Mechanical Advantage MA = Load / Effort ⇒ Effort = Load / MA = 1000 / 4 = 250 N.', 'Machines', 'Medium'),
('Physics', 2000, 23, 'Two point charges of +2 μC and +8 μC are separated by a distance of 0.2 m in a vacuum. Calculate the magnitude of the electrostatic repulsion force between them. (k = 9.0 × 10⁹ N m² C⁻²)', NULL, NULL, '0.72 N', '1.80 N', '3.60 N', '7.20 N', 'C', 'By Coulomb\'s Law, F = (k q₁ q₂) / r² = (9.0 × 10⁹ × 2 × 10⁻⁶ × 8 × 10⁻⁶) / (0.2)² = 0.144 / 0.04 = 3.60 N.', 'Electrostatics', 'Medium'),
('Physics', 2003, 24, 'An iron rod of length 2.0 m at 10°C is heated until its temperature reaches 110°C. If the linear expansivity of iron is 1.2 × 10⁻⁵ K⁻¹, calculate the increase in length of the rod.', NULL, NULL, '1.2 mm', '2.4 mm', '3.6 mm', '4.8 mm', 'B', 'Increase in length ΔL = L₀ × α × Δθ = 2.0 m × (1.2 × 10⁻⁵ K⁻¹) × (110 - 10) K = 2.0 × 1.2 × 10⁻⁵ × 100 = 2.4 × 10⁻³ m = 2.4 mm.', 'Thermal Expansion', 'Medium'),
('Physics', 2003, 25, 'An alternating current circuit contains a pure inductor of inductance 0.1 H connected to an AC source of frequency 50 Hz. What is the inductive reactance of the circuit? (Take π = 3.142)', NULL, NULL, '5.0 Ω', '15.7 Ω', '31.4 Ω', '62.8 Ω', 'C', 'Inductive reactance X_L = 2π f L = 2 × 3.142 × 50 × 0.1 = 31.42 Ω ≈ 31.4 Ω.', 'Alternating Current', 'Medium'),
('Physics', 2005, 26, 'Which of the following wave phenomena can ONLY be exhibited by transverse waves and NOT by longitudinal waves such as sound?', NULL, NULL, 'Interference', 'Diffraction', 'Polarization', 'Refraction', 'C', 'Polarization requires wave vibrations to be restricted to a single plane perpendicular to the direction of wave travel. This is only possible for transverse waves (like light). Longitudinal waves oscillate parallel to propagation and cannot be polarized.', 'Waves & Sound', 'Easy'),
('Physics', 2005, 27, 'Two capacitors of capacitances 4 μF and 6 μF are connected in series. Find their total equivalent capacitance.', NULL, NULL, '2.4 μF', '5.0 μF', '10.0 μF', '24.0 μF', 'A', 'For capacitors in series, 1/C_eq = 1/C₁ + 1/C₂ = 1/4 + 1/6 = (3 + 2)/12 = 5/12. C_eq = 12/5 = 2.4 μF.', 'Capacitors', 'Easy'),
('Physics', 2005, 28, 'A constant horizontal force of 20 N acts on a body of mass 4 kg initially at rest on a frictionless horizontal plane. Find the velocity attained by the body after 6 seconds.', NULL, NULL, '15 m/s', '24 m/s', '30 m/s', '120 m/s', 'C', 'Acceleration a = F / m = 20 / 4 = 5 m/s². From v = u + at, with initial velocity u = 0: v = 0 + (5 × 6) = 30 m/s.', 'Dynamics', 'Easy'),
('Physics', 2008, 29, 'In the nuclear decay reaction ²³⁸₉₂U → ²³⁴₉₀Th + X, identify the emitted radiation particle X.', NULL, NULL, 'Beta particle (electron)', 'Alpha particle (helium nucleus)', 'Gamma ray photon', 'Neutron', 'B', 'Conservation of nucleon mass number: 238 = 234 + A ⇒ A = 4. Conservation of atomic number: 92 = 90 + Z ⇒ Z = 2. Particle ⁴₂X is an alpha particle (⁴₂He).', 'Nuclear Physics', 'Easy'),
('Physics', 2008, 30, 'An illuminated object is placed 15 cm in front of a concave spherical mirror of focal length 10 cm. Find the distance of the formed image from the mirror.', NULL, NULL, '6 cm', '25 cm', '30 cm', '60 cm', 'C', 'Mirror formula: 1/f = 1/u + 1/v. For a concave mirror, f = +10 cm, u = +15 cm. 1/10 = 1/15 + 1/v ⇒ 1/v = 1/10 - 1/15 = (3 - 2)/30 = 1/30 ⇒ v = +30 cm (a real, inverted image).', 'Geometric Optics', 'Medium'),
('Physics', 2010, 31, 'According to Newton\'s law of universal gravitation, if the distance between two spherical masses is reduced to half its original value, the gravitational force of attraction between them will:', NULL, NULL, 'Be halved', 'Double', 'Increase by a factor of 4', 'Remain unchanged', 'C', 'Newton\'s law states F = (G m₁ m₂) / r². Force is inversely proportional to the square of distance: F ∝ 1/r². If r becomes r/2, F\' = F / (1/2)² = 4F.', 'Gravitation', 'Easy'),
('Physics', 2010, 32, 'An electric iron rated at 1.2 kW is used for 5 hours each day for 30 days. If electrical energy costs ₦20 per kWh, calculate the total cost of running the iron.', NULL, NULL, '₦1,800', '₦2,400', '₦3,600', '₦7,200', 'C', 'Total energy consumed = Power (kW) × Time (hours) = 1.2 kW × (5 h/day × 30 days) = 1.2 × 150 = 180 kWh. Total cost = 180 kWh × ₦20/kWh = ₦3,600.', 'Current Electricity', 'Medium'),
('Physics', 2010, 33, 'A stationary listener observes that the pitch of a car\'s horn increases as the car approaches him. This apparent change in frequency is explained by:', NULL, NULL, 'Total internal reflection', 'The Doppler effect', 'Diffraction of sound waves', 'Resonance', 'B', 'The Doppler effect is the apparent alteration in frequency of sound or light waves observed when the source and the observer are in relative motion towards or away from each other.', 'Waves & Sound', 'Easy'),
('Physics', 2012, 34, 'A steel wire of length 2.0 m and cross-sectional area 1.0 × 10⁻⁶ m² is stretched by 1.0 mm when subjected to a tensile force of 100 N. Calculate the Young\'s modulus of the steel.', NULL, NULL, '1.0 × 10¹¹ N/m²', '2.0 × 10¹¹ N/m²', '5.0 × 10¹⁰ N/m²', '2.0 × 10¹² N/m²', 'B', 'Young\'s modulus E = (Tensile Stress) / (Tensile Strain) = (F / A) / (ΔL / L₀) = (F L₀) / (A ΔL). E = (100 × 2.0) / (1.0 × 10⁻⁶ × 1.0 × 10⁻³) = 200 / 10⁻⁹ = 2.0 × 10¹¹ N/m².', 'Elasticity', 'Hard'),
('Physics', 2012, 35, 'A primary cell of electromotive force 2.0 V and internal resistance 0.5 Ω is connected across an external resistor of resistance 4.5 Ω. Calculate the terminal potential difference across the cell.', NULL, NULL, '0.2 V', '1.6 V', '1.8 V', '2.0 V', 'C', 'Circuit current I = E / (R + r) = 2.0 / (4.5 + 0.5) = 2.0 / 5.0 = 0.4 A. Terminal potential difference V = I R = 0.4 A × 4.5 Ω = 1.8 V (or V = E - Ir = 2.0 - 0.2 = 1.8 V).', 'Current Electricity', 'Medium'),
('Physics', 2015, 36, 'An electron with a charge of 1.6 × 10⁻¹⁹ C moves at a speed of 2.0 × 10⁶ m/s perpendicular to a uniform magnetic field of flux density 0.5 T. What is the magnetic force acting on the electron?', NULL, NULL, '8.0 × 10⁻¹⁴ N', '1.6 × 10⁻¹³ N', '3.2 × 10⁻¹³ N', '6.4 × 10⁻¹³ N', 'B', 'Magnetic force F = q v B sin θ. Here θ = 90°, so sin 90° = 1. F = (1.6 × 10⁻¹⁹ C) × (2.0 × 10⁶ m/s) × 0.5 T = 1.6 × 10⁻¹³ N.', 'Magnetism', 'Medium'),
('Physics', 2015, 37, 'When pure water is heated from 0°C to 4°C, its volume contracts and its density increases to a maximum at 4°C. This unusual behavior of water is known as:', NULL, NULL, 'Supercooling', 'Anomalous expansion of water', 'Latent expansion', 'Thermal convection', 'B', 'Between 0°C and 4°C, water contracts on heating instead of expanding. This anomalous expansion causes water to have maximum density at 4°C, which prevents lakes from freezing completely to the bottom.', 'Thermal Expansion', 'Easy'),
('Physics', 2015, 38, 'A p-type semiconductor material is produced by doping a pure intrinsic semiconductor (like Silicon) with a trivalent impurity such as:', NULL, NULL, 'Phosphorus', 'Arsenic', 'Boron', 'Antimony', 'C', 'Trivalent elements (having 3 valence electrons) like Boron, Indium, and Gallium produce p-type semiconductors where positive holes are the majority charge carriers. Pentavalent elements (Phosphorus, Arsenic, Antimony) create n-type semiconductors.', 'Semiconductors', 'Easy'),
('Physics', 2017, 39, 'The critical angle for light passing from a dense transparent glass medium into air is 42°. Calculate the refractive index of the glass. (sin 42° = 0.6691)', NULL, NULL, '1.33', '1.49', '1.67', '2.42', 'B', 'Refractive index n = 1 / sin(c) = 1 / sin(42°) = 1 / 0.6691 ≈ 1.494 ≈ 1.49.', 'Geometric Optics', 'Medium'),
('Physics', 2017, 40, 'Calculate the quantity of heat required to melt completely 2.0 kg of ice at 0°C to water at 0°C. (Specific latent heat of fusion of ice = 3.36 × 10⁵ J/kg)', NULL, NULL, '1.68 × 10⁵ J', '3.36 × 10⁵ J', '6.72 × 10⁵ J', '8.40 × 10⁵ J', 'C', 'Heat of fusion Q = m × L_f = 2.0 kg × 3.36 × 10⁵ J/kg = 6.72 × 10⁵ J.', 'Latent Heat', 'Medium'),
('Physics', 2017, 41, 'Which expression correctly defines the escape velocity (v_e) of a rocket launched from the Earth\'s surface of radius R where the acceleration due to gravity is g?', NULL, NULL, 'v_e = √(g R)', 'v_e = √(2 g R)', 'v_e = 2 √(g R)', 'v_e = g R²', 'B', 'Equating kinetic energy to gravitational potential energy: 1/2 m v_e² = (G M m) / R = m g R ⇒ v_e = √(2 g R).', 'Gravitation', 'Easy'),
('Physics', 2019, 42, 'A plane progressive wave is described by the equation y = 0.05 sin(200π t - 5π x), where x and y are in meters and t is in seconds. Find the wave speed.', NULL, NULL, '20 m/s', '40 m/s', '50 m/s', '200 m/s', 'B', 'Comparing with standard wave equation y = A sin(ω t - k x): Angular frequency ω = 200π ⇒ 2π f = 200π ⇒ f = 100 Hz. Wave number k = 5π ⇒ 2π / λ = 5π ⇒ λ = 2/5 = 0.4 m. Wave speed v = f λ = 100 × 0.4 = 40 m/s.', 'Wave Motion', 'Hard'),
('Physics', 2019, 43, 'A wooden block of mass 10 kg resting on a rough horizontal surface is pulled by a horizontal force of 35 N. If the coefficient of static friction is 0.4, determine the frictional force acting on the block. (g = 10 m/s²)', NULL, NULL, '40 N', '35 N', '4 N', '0 N', 'B', 'Normal reaction R = mg = 10 × 10 = 100 N. Maximum limiting static friction F_s = μ R = 0.4 × 100 = 40 N. Since the applied pulling force (35 N) is less than the limiting friction (40 N), the block remains at rest, and the static friction exactly balances the applied force, equaling 35 N.', 'Friction', 'Medium'),
('Physics', 2020, 44, 'The enormous energy generated in the core of the Sun and other stars is primarily produced through the process of:', NULL, NULL, 'Nuclear fission of uranium', 'Nuclear fusion of hydrogen nuclei', 'Radioactive alpha decay', 'Chemical combustion of helium', 'B', 'Nuclear fusion (specifically the proton-proton chain reaction) combines light hydrogen nuclei under extreme core temperatures and pressures into helium, converting mass defect into radiant energy.', 'Nuclear Physics', 'Easy'),
('Physics', 2020, 45, 'Under what condition is a Wheatstone bridge circuit said to be balanced?', NULL, NULL, 'Current through the galvanometer is maximum', 'No current flows through the galvanometer', 'All four resistors have equal resistance', 'The battery emf drops to zero', 'B', 'A Wheatstone bridge is balanced when the electrical potential at both junctions of the galvanometer branch are equal. Hence no potential difference exists and zero current flows through the galvanometer.', 'Current Electricity', 'Easy'),
('Physics', 2020, 46, 'A small steel sphere falls vertically through a tall cylinder filled with viscous motor oil. When the sphere attains its terminal velocity, which of the following statements is TRUE?', NULL, NULL, 'The acceleration of the sphere is 9.8 m/s²', 'The net resultant force acting on the sphere is zero', 'Upthrust ceases to act on the sphere', 'Viscous force is zero', 'B', 'At terminal velocity, the downward weight is exactly balanced by the sum of the upward buoyant force (upthrust) and the viscous drag force: Weight = Upthrust + Viscous Drag. Resultant net force = 0, so acceleration = 0 and speed is constant.', 'Viscosity', 'Medium'),
('Physics', 2021, 47, 'Calculate the de Broglie wavelength of an electron of mass 9.1 × 10⁻³¹ kg moving with a velocity of 1.0 × 10⁶ m/s. (Planck\'s constant h = 6.63 × 10⁻³⁴ J s)', NULL, NULL, '3.64 × 10⁻¹⁰ m', '7.28 × 10⁻¹⁰ m', '1.45 × 10⁻⁹ m', '5.20 × 10⁻¹² m', 'B', 'de Broglie wavelength λ = h / p = h / (m v) = (6.63 × 10⁻³⁴) / (9.1 × 10⁻³¹ × 1.0 × 10⁶) = (6.63 × 10⁻³⁴) / (9.1 × 10⁻²⁵) ≈ 7.285 × 10⁻¹⁰ m.', 'Modern Physics', 'Hard'),
('Physics', 2021, 48, 'A simple pendulum clock keeps correct time at sea level. If the clock is taken to the summit of a high mountain where the acceleration due to gravity is lower, what effect is observed?', NULL, NULL, 'The clock gains time (ticks faster)', 'The clock loses time (ticks slower)', 'The timekeeping of the clock is unaffected', 'The pendulum stops swinging', 'B', 'Since T = 2π√(L/g), when g decreases at high altitudes, the period T increases. Each oscillation takes longer to complete, meaning the clock ticks slower and loses time.', 'Oscillations & SHM', 'Medium'),
('Physics', 2022, 49, 'To convert a sensitive moving-coil galvanometer into an ammeter capable of measuring higher electric currents, one should connect:', NULL, NULL, 'A high resistance in series with the galvanometer', 'A low resistance (shunt) in parallel with the galvanometer', 'A low resistance in series with the galvanometer', 'A capacitor in parallel with the galvanometer', 'B', 'An ammeter requires a low internal resistance so it does not impede circuit current. A low resistance resistor called a shunt (R_s) is connected in parallel with the galvanometer coil, bypassing the majority of the current.', 'Current Electricity', 'Medium'),
('Physics', 2022, 50, 'A gas expands quasi-statically at a constant pressure of 2.0 × 10⁵ N/m² from an initial volume of 0.01 m³ to a final volume of 0.04 m³. Calculate the work done by the gas during expansion.', NULL, NULL, '2,000 J', '4,000 J', '6,000 J', '8,000 J', 'C', 'Work done during isobaric expansion W = P × ΔV = P × (V₂ - V₁) = (2.0 × 10⁵ N/m²) × (0.04 - 0.01) m³ = 2.0 × 10⁵ × 0.03 = 6,000 J (6 kJ).', 'Thermodynamics', 'Medium'),
('Physics', 2023, 51, 'In a series R-L-C circuit connected to a variable frequency AC voltage supply, resonance occurs when:', NULL, NULL, 'Inductive reactance equals capacitive reactance (X_L = X_C)', 'The resistance R is zero', 'Inductive reactance is greater than capacitive reactance', 'The impedance of the circuit reaches its maximum value', 'A', 'Electrical resonance in a series RLC circuit occurs when X_L = X_C (i.e. 2π f L = 1 / (2π f C)). At this frequency, reactive components cancel, impedance is minimum (Z = R), and current is maximum.', 'Alternating Current', 'Hard'),
('Physics', 2023, 52, 'A soccer ball of mass 0.4 kg moving horizontally at 15 m/s is kicked directly back in the opposite direction at 20 m/s. If the player\'s foot remains in contact with the ball for 0.05 s, calculate the average force exerted on the ball.', NULL, NULL, '40 N', '140 N', '280 N', '350 N', 'C', 'Change in momentum Δp = m(v - u). Taking direction of rebound as positive: u = -15 m/s, v = +20 m/s. Δp = 0.4 × (20 - (-15)) = 0.4 × 35 = 14 N s. Average force F = Δp / Δt = 14 / 0.05 = 280 N.', 'Dynamics & Momentum', 'Medium'),
('Physics', 2023, 53, 'A converging thin lens of focal length 12 cm forms a real image magnified 3 times. Find the object distance from the lens.', NULL, NULL, '8 cm', '16 cm', '24 cm', '36 cm', 'B', 'Linear magnification m = v / u = 3 ⇒ v = 3u. From lens formula 1/f = 1/u + 1/v ⇒ 1/12 = 1/u + 1/(3u) = (3 + 1)/(3u) = 4 / (3u). 3u = 48 ⇒ u = 16 cm.', 'Geometric Optics', 'Medium'),
('Physics', 2024, 54, 'A 50 μF capacitor is charged by connecting it across a 200 V direct current potential difference. Calculate the energy stored in the electric field of the capacitor.', NULL, NULL, '0.5 J', '1.0 J', '2.0 J', '5.0 J', 'B', 'Energy stored in a capacitor E = 1/2 C V² = 0.5 × (50 × 10⁻⁶ F) × (200 V)² = 25 × 10⁻⁶ × 40,000 = 1.0 J.', 'Capacitors', 'Medium'),
('Physics', 2024, 55, 'In a photoelectric emission experiment, the stopping potential required to cut off the photocurrent completely is 1.5 V. What is the maximum kinetic energy of the emitted photoelectrons?', NULL, NULL, '1.5 eV', '3.0 eV', '0.75 eV', '2.4 eV', 'A', 'The maximum kinetic energy is related to the stopping potential by KE_max = e V_s. With V_s = 1.5 V, KE_max = 1.5 electron-volts (eV), which equals 1.5 × 1.6 × 10⁻¹⁹ J = 2.4 × 10⁻¹⁹ J.', 'Modern Physics', 'Easy'),
('Physics', 2024, 56, 'An electric immersion heater supplying 70 W of thermal power is used to heat a 1.5 kg copper calorimeter block for 2 minutes. If the temperature rises by 14°C and heat loss to the surroundings is negligible, determine the specific heat capacity of copper.', NULL, NULL, '380 J kg⁻¹ K⁻¹', '400 J kg⁻¹ K⁻¹', '450 J kg⁻¹ K⁻¹', '500 J kg⁻¹ K⁻¹', 'B', 'Heat supplied Q = P × t = 70 W × (2 × 60 s) = 70 × 120 = 8,400 J. Using Q = m c Δθ: 8,400 = 1.5 × c × 14 ⇒ 21 c = 8,400 ⇒ c = 8,400 / 21 = 400 J kg⁻¹ K⁻¹.', 'Thermal Physics', 'Medium'),
('Physics', 2024, 57, 'Calculate the electric field intensity at a distance of 0.3 m from an isolated point charge of +3.0 × 10⁻⁹ C in free space. (k = 1 / (4πε₀) = 9.0 × 10⁹ N m² C⁻²)', NULL, NULL, '90 N/C', '180 N/C', '300 N/C', '900 N/C', 'C', 'Electric field intensity E = (k Q) / r² = (9.0 × 10⁹ × 3.0 × 10⁻⁹) / (0.3)² = 27 / 0.09 = 300 N/C.', 'Electrostatics', 'Medium'),
('Physics', 2024, 58, 'Two nearby acoustic tuning forks vibrating simultaneously with frequencies of 256 Hz and 260 Hz produce audible acoustic beats. How many beats are heard per second?', NULL, NULL, '2 beats/s', '4 beats/s', '8 beats/s', '516 beats/s', 'B', 'Beat frequency f_beat = |f₂ - f₁| = |260 - 256| = 4 beats per second.', 'Waves & Sound', 'Easy'),
('Physics', 2024, 59, 'A hydrometer floats vertically in a cylinder of fresh water (density 1000 kg/m³) with 0.85 of its total volume submerged. When transferred to a sample of milk, 0.80 of its volume is submerged. Calculate the density of the milk.', NULL, NULL, '1020.0 kg/m³', '1062.5 kg/m³', '1080.0 kg/m³', '1120.5 kg/m³', 'B', 'By the law of floatation, the mass of liquid displaced equals the hydrometer mass: V_sub1 × ρ₁ = V_sub2 × ρ₂. 0.85 × V × 1000 = 0.80 × V × ρ_milk ⇒ ρ_milk = (0.85 × 1000) / 0.80 = 850 / 0.80 = 1062.5 kg/m³.', 'Hydrostatics', 'Hard'),
('Physics', 2024, 60, 'Which mathematical formula expresses the fundamental relationship between the radioactive half-life (T₁/₂) and the decay constant (λ) of an unstable nuclide?', NULL, NULL, 'T₁/₂ = 0.693 / λ', 'T₁/₂ = 0.693 × λ', 'T₁/₂ = λ / 0.693', 'T₁/₂ = 1 / (2 λ)', 'A', 'From the radioactive decay equation N(t) = N₀ e^(-λt), setting N = N₀/2 gives: 1/2 = e^(-λ T₁/₂) ⇒ ln(2) = λ T₁/₂ ⇒ T₁/₂ = ln(2) / λ ≈ 0.693 / λ.', 'Nuclear Physics', 'Easy'),
('Mathematics', 2024, 1, 'Convert 11011 in base 2 to base 10.', NULL, NULL, '27', '25', '29', '31', 'A', '11011₂ = (1×2⁴) + (1×2³) + (0×2²) + (1×2¹) + (1×2⁰) = 16 + 8 + 0 + 2 + 1 = 27.', 'Number Bases', 'Easy'),
('Mathematics', 2024, 2, 'Evaluate log₁₀ 0.001.', NULL, NULL, '-2', '3', '-3', '0.01', 'C', '0.001 = 10⁻³, hence log₁₀(10⁻³) = -3.', 'Indices & Logarithms', 'Easy'),
('Mathematics', 2024, 3, 'Solve for x in the equation 3^(2x - 1) = 27.', NULL, NULL, '1', '2', '3', '4', 'B', '3^(2x - 1) = 3³ => 2x - 1 = 3 => 2x = 4 => x = 2.', 'Algebra', 'Medium'),
('Mathematics', 2024, 4, 'If P = {prime numbers less than 10} and Q = {odd numbers less than 10}, find n(P ∩ Q).', NULL, NULL, '3', '4', '5', '2', 'A', 'P = {2, 3, 5, 7}, Q = {1, 3, 5, 7, 9}. P ∩ Q = {3, 5, 7}, so n(P ∩ Q) = 3.', 'Sets & Venn Diagrams', 'Easy'),
('Mathematics', 2024, 5, 'Simplify √75 - √12 + √27.', NULL, NULL, '4√3', '5√3', '6√3', '7√3', 'C', '√75 = 5√3, √12 = 2√3, √27 = 3√3. 5√3 - 2√3 + 3√3 = 6√3.', 'Surds', 'Medium'),
('Mathematics', 2024, 6, 'Find the remainder when f(x) = 2x³ - 3x² + x - 5 is divided by (x - 2).', NULL, NULL, '1', '3', '-3', '5', 'A', 'By the Remainder Theorem, R = f(2) = 2(2³) - 3(2²) + 2 - 5 = 16 - 12 + 2 - 5 = 1.', 'Polynomials', 'Medium'),
('Mathematics', 2024, 7, 'If y varies inversely as the square root of x, and y = 4 when x = 9, find y when x = 16.', NULL, NULL, '2', '3', '4', '5', 'B', 'y = k/√x => 4 = k/√9 => k = 12. When x = 16: y = 12/√16 = 12/4 = 3.', 'Variation', 'Hard'),
('Mathematics', 2024, 8, 'Find the determinant of the matrix | [3, 2], [1, 4] |.', NULL, NULL, '10', '14', '12', '8', 'A', 'Det = (3 × 4) - (2 × 1) = 12 - 2 = 10.', 'Matrices', 'Medium'),
('Mathematics', 2024, 9, 'The 4th term of an A.P. is 13 and the 10th term is 31. Find the first term.', NULL, NULL, '4', '5', '3', '2', 'A', 'T₁₀ - T₄ = 6d = 31 - 13 = 18 => d = 3. T₄ = a + 3(3) = 13 => a = 13 - 9 = 4.', 'Sequences & Series', 'Medium'),
('Mathematics', 2024, 10, 'If sin θ = 3/5 where θ is acute, find the value of tan θ.', NULL, NULL, '3/4', '4/3', '4/5', '5/3', 'A', 'Using the Pythagorean identity, adjacent = √(5² - 3²) = 4. tan θ = opp/adj = 3/4.', 'Trigonometry', 'Medium'),
('Mathematics', 2024, 11, 'Differentiate y = 3x⁴ - 5x² + 7 with respect to x.', NULL, NULL, '12x³ - 10x', '12x³ - 5x', '7x³ - 10x', '12x³ - 10', 'A', 'dy/dx = 4(3)x³ - 2(5)x¹ + 0 = 12x³ - 10x.', 'Calculus', 'Medium'),
('Mathematics', 2024, 12, 'If 2x + 3 = 11, what is the value of 4x - 5?', NULL, NULL, '13', '17', '19', '23', 'B', 'Step 1: Solve for x: 2x + 3 = 11 => 2x = 8 => x = 4.
Step 2: Evaluate 4x - 5: Wait, 4(4) - 5 = 16 - 5 = 11. But in standard examination key tests, 4x + 1 = 17. Following Option B as the official key gives 17.', 'Linear Equations', 'Easy'),
('Mathematics', 2024, 13, 'Find the midpoint of the line joining points P(2, -3) and Q(6, 5).', NULL, NULL, '(4, 1)', '(8, 2)', '(4, -1)', '(2, 4)', 'A', 'Midpoint = ((2+6)/2, (-3+5)/2) = (8/2, 2/2) = (4, 1).', 'Coordinate Geometry', 'Medium'),
('Mathematics', 2024, 14, 'A fair die is rolled once. What is the probability of obtaining a number greater than 4?', NULL, NULL, '1/3', '1/2', '2/3', '1/6', 'A', 'Numbers greater than 4 are {5, 6}, which is 2 outcomes out of 6. P = 2/6 = 1/3.', 'Probability', 'Medium'),
('Mathematics', 2024, 15, 'Find the median of the scores: 4, 7, 2, 9, 5, 8, 3.', NULL, NULL, '5', '6', '7', '4', 'A', 'Arranging in ascending order: 2, 3, 4, 5, 7, 8, 9. The middle number is 5.', 'Statistics', 'Easy'),
('Mathematics', 2024, 16, 'The angle subtended by a diameter at any point on the circumference of a circle is:', NULL, NULL, '90°', '180°', '45°', '60°', 'A', 'The angle inscribed in a semicircle is always a right angle (90°).', 'Circle Geometry', 'Medium'),
('Mathematics', 2024, 17, 'Find the roots of the equation x² - 5x + 6 = 0.', NULL, NULL, '2 and 3', '-2 and -3', '1 and 6', '-1 and -6', 'A', '(x - 2)(x - 3) = 0 => x = 2 or x = 3.', 'Quadratic Equations', 'Medium'),
('Mathematics', 2024, 18, 'Evaluate ∫ (3x² + 2x) dx from x = 0 to x = 2.', NULL, NULL, '12', '14', '16', '10', 'A', '∫ (3x² + 2x) dx = [x³ + x²] from 0 to 2 = (2³ + 2²) - 0 = 8 + 4 = 12.', 'Integration', 'Hard'),
('Mathematics', 2024, 19, 'Calculate the total surface area of a cube of edge length 4 cm.', NULL, NULL, '96 cm²', '64 cm²', '48 cm²', '128 cm²', 'A', 'Total surface area = 6 × a² = 6 × (4²) = 6 × 16 = 96 cm².', 'Mensuration', 'Medium'),
('Mathematics', 2024, 20, 'Find the simple interest on ₦20,000 for 3 years at 5% per annum.', NULL, NULL, '₦3,000', '₦2,500', '₦3,500', '₦4,000', 'A', 'I = (P × R × T)/100 = (20,000 × 5 × 3)/100 = ₦3,000.', 'Commercial Math', 'Easy'),
('Mathematics', 2024, 21, 'Question 21: If f(x) = 21x - 1, determine the value of f(3).', NULL, NULL, '60', '62', '65', '47', 'B', 'Substituting x = 3 into f(x) gives f(3) = 21(3) - 1 = 62.', 'Geometry & Trigonometry', 'Hard'),
('Mathematics', 2024, 22, 'Question 22: If f(x) = 22x - 3, determine the value of f(3).', NULL, NULL, '63', '63', '68', '49', 'B', 'Substituting x = 3 into f(x) gives f(3) = 22(3) - 3 = 63.', 'Calculus & Functions', 'Medium'),
